      if (marker && marker !== ref.contractId) {
        throw new Error(
          purpose + ': anchor key "' + ref.anchorKey + '" belongs to contractId "' +
          marker + '", not "' + ref.contractId + '" — refusing contradictory identity',
        );
      }
      return anchored[0];
